import React, { useState } from "react";
import { api, saveSession } from "./api.js";

// CRM website (outside Telegram): login + password. Passwords are generated by an admin in «Команда».
export default function Login({ notice }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState(notice || "");

  async function submit(e) {
    e.preventDefault();
    setBusy(true); setMsg("");
    try {
      const r = await api("/api/v1/auth/login", { method: "POST", body: { username: username.trim().replace(/^@+/, ""), password } });
      saveSession({ token: r.token, username: r.username, expires: r.expires });
      window.location.reload();
    } catch (e) { setMsg(e.message); setBusy(false); }
  }

  return (
    <main className="app login-page">
      <header><div><p className="eyebrow">BROKER CRM</p><h1>Вход</h1></div></header>
      <form className="card login-card" onSubmit={submit}>
        <label>Логин<input value={username} onChange={e => setUsername(e.target.value)} autoComplete="username" autoCapitalize="none" spellCheck="false" placeholder="Telegram username без @" /></label>
        <label>Пароль<input type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" /></label>
        <button className="primary" type="submit" disabled={busy || !username.trim() || !password}>{busy ? "Вхожу…" : "Войти"}</button>
        {msg && <div className="team-message">{msg}</div>}
        <p className="subtitle">Логин и пароль выдаёт админ во вкладке «Команда». Забыл пароль — попроси новый.</p>
      </form>
    </main>
  );
}
